import { useEffect, useMemo, useState } from 'react';
import { resolveAssetUrl } from '../../config/loadConfig';
import type { MapConfig } from '../../config/schema';
import {
  IMAGE_SCALE_LIMITS, TILE_SIZE, fitContain, fitCover, lngToMercator, mercatorAspect,
  scaleLimitsFor, tilesForViewport, visibleRect, zoomForBounds,
  type MapTransform, type ScaleLimits, type Size, type TilePlacement,
} from './mapNavigation';

/**
 * 瓦片底图层的几何与取图逻辑（从 `MapPage.tsx` 原样搬出，行为一字未改）。
 *
 * 抽出来的唯一理由：新地图壳与旧地图页要渲染**同一套**瓦片层，而层级选择里那几条
 * 踩过坑的规则（DPR 参与选层、稳定 140ms 再换层、备用源按同一 z/x/y 切换、
 * 从可见范围中心往外排队）不能有第二份实现。
 */

const EMPTY_SIZE: Size = { width: 0, height: 0 };

/** 瓦片模式下用于推算层级的虚拟底图宽度。 */
const TILE_BASE_PX = 1024;

type Fitted = ReturnType<typeof fitCover>;

/** 带上备用源地址的瓦片（主源连续失败后 `TileImage` 会切过去）。 */
export type MapTile = TilePlacement & { fallbackUrl?: string };

export interface MapTileSet {
  /** 瓦片底图没有天然尺寸，按经纬度范围的墨卡托宽高比给一个等价尺寸。 */
  tileSize: Size;
  /** 静态图用原图尺寸，瓦片图用 `tileSize`。 */
  naturalSize: Size;
  box: Size;
  origin: Fitted['origin'];
  ready: boolean;
  /** 整幅范围刚好铺满时的瓦片层级；`initialView.zoom` 与缩放倍数都以它为基准。 */
  baseZoom: number;
  limits: ScaleLimits;
  /** 目标层级（跟着缩放动画逐帧变）。 */
  zoom: number;
  /** 实际用于取瓦片的层级（稳定 140ms 后才跟进）。 */
  settledZoom: number;
  tiles: MapTile[];
}

export interface UseMapTilesOptions {
  basemap: MapConfig['basemap'] | undefined;
  /** 舞台量到的尺寸（CSS 像素）。 */
  container: Size;
  /** 静态底图的原始像素尺寸（瓦片底图不用它）。 */
  natural: Size;
  transform: MapTransform;
  /** 设备像素比，参与瓦片层级选择。 */
  pixelRatio: number;
  /** 进全景的过渡期：保留当前稳定层级，避免为即将被遮住的放大视野请求新瓦片。 */
  hold?: boolean;
  /** 直达漫游路由：仍允许首次初始化层级，之后冻结，避免 iOS WebKit 与 720yun iframe 争用解码资源。 */
  freezeAfterInit?: boolean;
}

export function useMapTiles({
  basemap, container, natural, transform, pixelRatio, hold = false, freezeAfterInit = false,
}: UseMapTilesOptions): MapTileSet {
  const tileSize = useMemo<Size>(() => {
    if (basemap?.kind !== 'tiles') return EMPTY_SIZE;
    return { width: TILE_BASE_PX, height: TILE_BASE_PX / mercatorAspect(basemap.bounds) };
  }, [basemap]);
  const naturalSize = basemap?.kind === 'tiles' ? tileSize : natural;

  // 瓦片底图用 cover：铺满舞台，左右（宽屏下）或上下（竖屏下）不留空白；静态图仍用 contain，保证整幅可见。
  const { box, origin } = useMemo<Fitted>(
    () => (basemap?.kind === 'tiles' ? fitCover(naturalSize, container) : fitContain(naturalSize, container)),
    [basemap?.kind, naturalSize, container],
  );
  const ready = box.width > 0 && box.height > 0;
  const baseZoom = useMemo(
    () => (basemap?.kind === 'tiles' && ready ? zoomForBounds(basemap.bounds, box.width) : 0),
    [basemap, box.width, ready],
  );
  /**
   * 缩放上下限。瓦片底图的上限取「正好能放大到 maxZoom」，
   * 因此从全域到最深一层可以一路自由缩放，不再分两级。
   */
  const limits = useMemo<ScaleLimits>(
    () => (basemap?.kind === 'tiles' && ready
      ? scaleLimitsFor(basemap.minZoom, basemap.maxZoom, baseZoom)
      : IMAGE_SCALE_LIMITS),
    [basemap, baseZoom, ready],
  );
  const zoom = useMemo(() => {
    if (basemap?.kind !== 'tiles' || !ready) return 0;
    const base = baseZoom + Math.round(Math.log2(transform.scale));
    /*
     * 让"一张瓦片"落在约 256 个**设备像素**上——源图就是 256px，此时 1:1 最清晰。
     * 更粗（被放大）会发虚，更细（被缩小）白费流量。
     * 这一项在高分屏上尤其关键：DPR 3 的手机若按 CSS 像素选层级，源图会被放大 1.7 倍。
     *
     * 取整方式就用 `round`（"最近的层级"）：实测 `transform.scale` 与"正好铺满"的倍数之间
     * 关系使同一视口的瓦片像素宽度只有 ~0.93 / 1.86 两档，所以可选层级里"被放大"的那个总是 ≥1.9×。
     * 曾经想"只在会被拉伸时才升层"（阈值 1.15 + floor/ceil），结果把桌面档推到了 1.91× 的糊图，
     * 被 `verify-map-tiles.mjs` 拦住并回退 —— 省请求要靠下面的"稳定后再换层"，不是靠降清晰度。
     */
    const spanX = lngToMercator(basemap.bounds.east) - lngToMercator(basemap.bounds.west);
    const tileLayoutPx = box.width / (2 ** base * spanX);
    const tileDevicePx = tileLayoutPx * transform.scale * pixelRatio;
    const crispStep = Number.isFinite(tileDevicePx) && tileDevicePx > 0
      ? Math.round(Math.log2(tileDevicePx / TILE_SIZE))
      : 0;
    return Math.max(basemap.minZoom, Math.min(basemap.maxZoom, base + crispStep));
  }, [baseZoom, basemap, box.width, pixelRatio, ready, transform.scale]);
  /**
   * 实际用来选瓦片的层级：**稳定 140ms 之后才生效**。
   *
   * 缩放/下钻动画期间每一帧都会算出新的层级，直接跟着渲染的话，同一屏会反复请求好几套瓦片
   * （实测初始化一次就打了 48 个瓦片请求，而屏幕上只要 12 张）。手机上这会把同一 host 的连接数
   * 挤爆 —— 部分请求失败 → 瓦片空白，正是"iOS 上加载不出来"的放大器。
   * 停手后立刻生效，用户只慢 140ms，看不出差别。
   */
  const [settledZoom, setSettledZoom] = useState(0);
  useEffect(() => {
    if (!zoom || hold || (freezeAfterInit && settledZoom > 0)) return;
    const timer = window.setTimeout(() => setSettledZoom(zoom), 140);
    return () => window.clearTimeout(timer);
  }, [zoom, hold, freezeAfterInit, settledZoom]);

  const tiles = useMemo<MapTile[]>(() => {
    if (basemap?.kind !== 'tiles' || !ready || !settledZoom) return [];
    // 在线 HTTPS 模板原样保留；其他配置的相对路径仍由 BASE_URL 解析。
    const view = visibleRect(transform, box, container, origin);
    /** 同一份 bounds/层级/可见范围下取某一套模板的瓦片；overlay 加前缀避免 key 冲突。 */
    const layerOf = (template: string, overlay: boolean, subdomains: string[] = []) =>
      tilesForViewport(basemap.bounds, settledZoom, view, resolveAssetUrl(template), subdomains)
        .map(tile => (overlay ? { ...tile, key: `overlay-${tile.key}`, overlay: true } : tile));

    const primary = layerOf(basemap.urlTemplate, false, basemap.subdomains);
    if (basemap.overlayTemplate) primary.push(...layerOf(basemap.overlayTemplate, true, basemap.subdomains));

    /*
     * 备用源：主源出错后按**同一个 key**（同一 z/x/y）切过去。
     * 备用源是别的厂商，没有 t0~t7，所以不传 subdomains。
     */
    const fallback = new Map<string, string>();
    if (basemap.fallbackTemplate) {
      for (const tile of layerOf(basemap.fallbackTemplate, false)) fallback.set(tile.key, tile.url);
      if (basemap.fallbackOverlayTemplate) {
        for (const tile of layerOf(basemap.fallbackOverlayTemplate, true)) fallback.set(tile.key, tile.url);
      }
    }

    /*
     * 从可见范围中心往外排：分批挂载时先出中间，用户看到的是"从中心铺开"。
     * 底图排完再排标注，保证先有底图、后有注记。
     */
    const centerX = (view.x0 + view.x1) / 2;
    const centerY = (view.y0 + view.y1) / 2;
    const distance = (tile: { left: number; top: number; width: number; height: number }) =>
      ((tile.left + tile.width / 2 - centerX) ** 2) + ((tile.top + tile.height / 2 - centerY) ** 2);
    const ordered = [
      ...primary.filter(tile => !tile.overlay).sort((a, b) => distance(a) - distance(b)),
      ...primary.filter(tile => tile.overlay).sort((a, b) => distance(a) - distance(b)),
    ];

    return ordered.map(tile => ({ ...tile, fallbackUrl: fallback.get(tile.key) }));
  }, [basemap, box, container, ready, settledZoom, transform, origin]);

  return { tileSize, naturalSize, box, origin, ready, baseZoom, limits, zoom, settledZoom, tiles };
}
